# Let's fetch all notes to ensure we have all trip-related notes.
all_notes = []
page_index = 0
while True:
    page = apis.simple_note.search_notes(access_token=simple_note_login['access_token'], page_index=page_index, page_limit=20)
    if not page:
        break
    all_notes.extend(page)
    if len(page) < 20:
        break
    page_index += 1
print(f"Total notes: {len(all_notes)}")
# Print titles and ids for trip-related ones
for note in all_notes:
    if any(word in note['title'].lower() for word in ['trip', 'expense', 'expenditure', 'road']):
        print(note['note_id'], note['title'])

